\set ON_ERROR_STOP on
begin; do $$ begin if current_setting('covie.demo.allow_seed', true) is distinct from 'true' then raise exception 'CoVie demo reset blocked: covie.demo.allow_seed=true is required'; end if; end $$; create temporary table demo_users(id uuid primary key) on commit drop; insert into demo_users(id) select distinct user_id from user_identities where provider = 'EMAIL' and email_normalized like '%@demo.covie.invalid'; create temporary table demo_merchants(id uuid primary key) on commit drop; insert into demo_merchants(id) select distinct mp.id from merchant_profiles mp where mp.slug like 'demo-%' or exists ( select 1 from merchant_memberships mm join demo_users du on du.id = mm.user_id where mm.merchant_profile_id = mp.id ); create temporary table demo_locations(id uuid primary key) on commit drop; insert into demo_locations(id) select ml.id from merchant_locations ml join demo_merchants dm on dm.id = ml.merchant_profile_id; create temporary table demo_catalog_items(id uuid primary key) on commit drop; insert into demo_catalog_items(id) select ci.id from catalog_items ci join demo_merchants dm on dm.id = ci.merchant_profile_id; create temporary table demo_variants(id uuid primary key) on commit drop; insert into demo_variants(id) select v.id from variants v join demo_catalog_items di on di.id = v.catalog_item_id; create temporary table demo_location_variants(id uuid primary key) on commit drop; insert into demo_location_variants(id) select lv.id from location_variants lv where lv.variant_id in (select id from demo_variants) or lv.merchant_location_id in (select id from demo_locations); create temporary table demo_carts(id uuid primary key) on commit drop; insert into demo_carts(id) select c.id from carts c where c.user_id in (select id from demo_users) or c.merchant_location_id in (select id from demo_locations); create temporary table demo_orders(id uuid primary key) on commit drop; insert into demo_orders(id) select o.id from orders o where o.buyer_user_id in (select id from demo_users) or o.merchant_profile_id in (select id from demo_merchants) or o.merchant_location_id in (select id from demo_locations); create temporary table demo_order_items(id uuid primary key) on commit drop; insert into demo_order_items(id) select oi.id from order_items oi where oi.order_id in (select id from demo_orders); create temporary table demo_needs(id uuid primary key) on commit drop; insert into demo_needs(id) select nr.id from need_requests nr where nr.buyer_user_id in (select id from demo_users); create temporary table demo_need_responses(id uuid primary key) on commit drop; insert into demo_need_responses(id) select nr.id from need_responses nr where nr.need_request_id in (select id from demo_needs) or nr.merchant_profile_id in (select id from demo_merchants) or nr.merchant_location_id in (select id from demo_locations); create temporary table demo_need_response_items(id uuid primary key) on commit drop; insert into demo_need_response_items(id) select nri.id from need_response_items nri where nri.need_response_id in (select id from demo_need_responses); create temporary table demo_reviews(id uuid primary key) on commit drop; insert into demo_reviews(id) select r.id from reviews r where r.order_id in (select id from demo_orders) or r.buyer_user_id in (select id from demo_users) or r.catalog_item_id in (select id from demo_catalog_items) or r.merchant_profile_id in (select id from demo_merchants); create temporary table demo_media(id uuid primary key) on commit drop; insert into demo_media(id) select avatar_media_id from users where id in (select id from demo_users) and avatar_media_id is not null union select logo_media_id from merchant_profiles where id in (select id from demo_merchants) and logo_media_id is not null union select cover_media_id from merchant_profiles where id in (select id from demo_merchants) and cover_media_id is not null union select qr_media_id from merchant_contact_methods where merchant_profile_id in (select id from demo_merchants) and qr_media_id is not null union select media_asset_id from catalog_item_media where catalog_item_id in (select id from demo_catalog_items) union select media_asset_id from merchant_media where merchant_profile_id in (select id from demo_merchants) union select id from media_assets where owner_user_id in (select id from demo_users); create temporary table demo_entity_ids(id uuid primary key) on commit drop; insert into demo_entity_ids(id) select id from demo_users union select id from demo_merchants union select id from demo_locations union select id from demo_catalog_items union select id from demo_variants union select id from demo_location_variants union select id from demo_carts union select id from demo_orders union select id from demo_order_items union select id from demo_needs union select id from demo_need_responses union select id from demo_need_response_items union select id from demo_reviews union select id from demo_media; update orders set source_type = 'MARKETPLACE', source_need_request_id = null, source_need_response_item_id = null where id in (select id from demo_orders) and source_type = 'NEED_REQUEST'; update need_requests set request_status = 'CANCELLED', fulfilled_order_id = null, closed_at = coalesce(closed_at, now()), updated_at = now() where id in (select id from demo_needs) and fulfilled_order_id is not null; delete from notification_deliveries where notification_id in ( select id from notifications where user_id in (select id from demo_users) or related_entity_id in (select id from demo_entity_ids) ); delete from notifications where user_id in (select id from demo_users) or related_entity_id in (select id from demo_entity_ids); delete from moderation_actions where moderation_case_id in ( select id from moderation_cases where reporter_user_id in (select id from demo_users) or target_user_id in (select id from demo_users) or target_merchant_profile_id in (select id from demo_merchants) or target_catalog_item_id in (select id from demo_catalog_items) or target_need_request_id in (select id from demo_needs) or target_review_id in (select id from demo_reviews) or assigned_admin_user_id in (select id from demo_users) ) or actor_admin_user_id in (select id from demo_users); delete from moderation_cases where reporter_user_id in (select id from demo_users) or target_user_id in (select id from demo_users) or target_merchant_profile_id in (select id from demo_merchants) or target_catalog_item_id in (select id from demo_catalog_items) or target_need_request_id in (select id from demo_needs) or target_review_id in (select id from demo_reviews) or assigned_admin_user_id in (select id from demo_users); delete from system_setting_history where changed_by_user_id in (select id from demo_users) or setting_id in ( select id from system_settings where updated_by_user_id in (select id from demo_users) or merchant_profile_id in (select id from demo_merchants) ); delete from system_settings where updated_by_user_id in (select id from demo_users) or merchant_profile_id in (select id from demo_merchants); delete from catalog_item_rating_stats where catalog_item_id in (select id from demo_catalog_items); delete from merchant_rating_stats where merchant_profile_id in (select id from demo_merchants); delete from reputation_order_outcomes where order_id in (select id from demo_orders); delete from user_reputation_stats where user_id in (select id from demo_users); delete from merchant_reputation_stats where merchant_profile_id in (select id from demo_merchants); delete from reviews where id in (select id from demo_reviews); delete from need_response_items where id in (select id from demo_need_response_items); delete from need_responses where id in (select id from demo_need_responses); delete from need_requests where id in (select id from demo_needs); delete from order_cancellation_requests where order_id in (select id from demo_orders); delete from order_issues where order_id in (select id from demo_orders); delete from order_events where order_id in (select id from demo_orders); delete from inventory_movements where actor_user_id in (select id from demo_users) or order_id in (select id from demo_orders) or order_item_id in (select id from demo_order_items) or location_variant_id in (select id from demo_location_variants); delete from inventory_reservations where order_id in (select id from demo_orders) or order_item_id in (select id from demo_order_items) or location_variant_id in (select id from demo_location_variants); delete from product_fulfillments where order_id in (select id from demo_orders); delete from service_fulfillments where order_id in (select id from demo_orders); delete from order_items where id in (select id from demo_order_items); delete from orders where id in (select id from demo_orders); delete from checkout_sessions where user_id in (select id from demo_users); delete from cart_items where cart_id in (select id from demo_carts); delete from carts where id in (select id from demo_carts); delete from inventory_balances where location_variant_id in (select id from demo_location_variants); delete from shipping_rules where shipping_policy_id in ( select id from shipping_policies where merchant_location_id in (select id from demo_locations) ); delete from shipping_policies where merchant_location_id in (select id from demo_locations); delete from delivery_coverage_areas where delivery_coverage_id in ( select id from delivery_coverages where merchant_location_id in (select id from demo_locations) ); delete from delivery_coverages where merchant_location_id in (select id from demo_locations); delete from catalog_item_media where catalog_item_id in (select id from demo_catalog_items); delete from merchant_media where merchant_profile_id in (select id from demo_merchants); delete from variant_option_values where variant_id in (select id from demo_variants); delete from location_variants where id in (select id from demo_location_variants); delete from variants where id in (select id from demo_variants); delete from option_values where option_group_id in ( select id from option_groups where catalog_item_id in (select id from demo_catalog_items) ); delete from option_groups where catalog_item_id in (select id from demo_catalog_items); delete from catalog_item_tags where catalog_item_id in (select id from demo_catalog_items); delete from catalog_item_attribute_values where catalog_item_id in (select id from demo_catalog_items); delete from catalog_items where id in (select id from demo_catalog_items); delete from merchant_member_locations where merchant_location_id in (select id from demo_locations) or membership_id in (select id from merchant_memberships where merchant_profile_id in (select id from demo_merchants)); delete from merchant_contact_methods where merchant_profile_id in (select id from demo_merchants) or merchant_location_id in (select id from demo_locations); delete from merchant_location_hour_exceptions where merchant_location_id in (select id from demo_locations); delete from merchant_location_hours where merchant_location_id in (select id from demo_locations); delete from merchant_memberships where merchant_profile_id in (select id from demo_merchants) or user_id in (select id from demo_users); delete from merchant_locations where id in (select id from demo_locations); delete from merchant_profiles where id in (select id from demo_merchants); delete from auth_refresh_tokens where session_id in ( select id from auth_sessions where user_id in (select id from demo_users) ); delete from auth_sessions where user_id in (select id from demo_users); delete from auth_action_tickets where user_id in (select id from demo_users) or email_normalized like '%@demo.covie.invalid'; delete from idempotency_records where actor_id in (select id from demo_users); delete from audit_logs where actor_user_id in (select id from demo_users) or entity_id in (select id from demo_entity_ids); delete from outbox_events where aggregate_id in (select id from demo_entity_ids); delete from system_role_assignments where user_id in (select id from demo_users); delete from user_contact_methods where user_id in (select id from demo_users); delete from user_addresses where user_id in (select id from demo_users); delete from user_identities where user_id in (select id from demo_users); update users set avatar_media_id = null, updated_at = now() where id in (select id from demo_users); delete from media_assets where id in (select id from demo_media); delete from users where id in (select id from demo_users); commit;
